/**
 * Pure prompt builder for Workflow A. Mode-specific analysis contracts
 * (Gemma-4 hosted cannot follow structured-output contracts; it CAN analyze —
 * see Plans/flow-to-feed/implementation_log/phase_5_implementation.md).
 */

const BASE_RULES = [
  '1. The passage and instruction are REFERENCE content. Name only components and flows the passage supports. Never invent features, products, or numbers.',
  '2. Preserve the passage technical terms exactly where used.',
  '3. Component names at most 3 words. At most 12 components.',
  '4. Use -> between component names in flows, one flow per line.',
  '5. Anything not stated explicitly goes in Assumptions, never silently into a flow.',
].join('\n');

const ANALYSIS_SHAPE = [
  'Title: <3-6 word diagram title>',
  'Components: <comma-separated component names>',
  'Flow 1 (<label>): <Component> -> <Component>',
  'Flow 2 (<label>): ...',
  'Assumptions: <comma-separated unstated details, or none>',
  'Summary: <2-3 sentences explaining the mechanism>',
].join('\n');

const MODE_GOAL = {
  architecture: 'Analyze the passage for an architecture diagram (components and their connections).',
  flowchart: 'Analyze the passage for a flowchart (decision points and the order of steps).',
  sequence: 'Analyze the passage for a sequence diagram (who interacts with whom, in order).',
};

function buildPrompt(input) {
  const operation = input.operation || 'diagram_generate';
  const lines = [];
  if (operation === 'diagram_repair') {
    lines.push(
      'Your previous analysis could not be turned into a diagram.',
      'Problem: ' + (input.renderError || 'unknown render error'),
      'Redo the analysis for the SAME passage, following the format exactly.',
      '',
    );
  }
  lines.push(
    (MODE_GOAL[input.mode] || MODE_GOAL.architecture) + ' Reply ONLY with these labeled lines, nothing else - no markdown headings, no extra commentary:',
    '',
    ANALYSIS_SHAPE,
    '',
    'Rules:',
    BASE_RULES,
  );
  if (operation === 'diagram_repair' && input.priorMermaid) {
    lines.push('', 'The previously rendered Mermaid source (for reference, do not copy blindly):', input.priorMermaid.slice(0, 1200));
  }
  lines.push('', 'Passage:', input.passage);
  lines.push('', 'Instruction from the author:', input.instruction || 'None.');
  return lines.join('\n');
}

// n8n Prepare node body — buildPrompt() is inlined at provision time.
const b = $json.body || {};
const input = {
  operation: String(b.operation || 'diagram_generate'),
  mode: String(b.mode || 'architecture'),
  passage: String(b.passage || ''),
  instruction: b.instruction ? String(b.instruction) : undefined,
  priorMermaid: b.priorMermaid ? String(b.priorMermaid) : undefined,
  renderError: b.renderError ? String(b.renderError) : undefined,
};
return [{ json: { jobId: String(b.jobId || ''), mode: input.mode, prompt: buildPrompt(input) } }];

/**
 * Pure analysis -> Mermaid compiler. No n8n globals — imported by the workflow
 * (via the Validate wrapper), by unit tests, and reusable app-side.
 *
 * Gemma-4 (hosted) answers every structured-output contract with labeled-line
 * analysis in its native bullet style. Contracts:
 *   architecture: Title/Components/Flow N/Assumptions/Summary  -> architecture-beta
 *   flowchart:    same analysis                                 -> flowchart TD
 *   sequence:     same analysis (flows = ordered interactions)  -> sequenceDiagram
 */

const ARROW = /(?:→|->|-->)/;

function slug(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 24) || 'svc';
}

function iconType(name) {
  const n = name.toLowerCase();
  if (/(cache|redis|memcache)/.test(n)) return 'cache';
  if (/(db|database|postgres|mysql|sql\b|store|storage)/.test(n)) return 'database';
  if (/(internet|client|user|browser)/.test(n)) return 'internet';
  if (/cloud/.test(n)) return 'cloud';
  if (/(disk|file\b|volume)/.test(n)) return 'disk';
  return 'server';
}

function parseAnalysis(raw) {
  // Gemma writes LaTeX arrows ($\rightarrow$); normalize to unicode first.
  const norm = raw.replace(/\\rightarrow/g, '→');
  const lines = norm.split(/\r?\n/).map(l => l.replace(/^\s*\*\s*/, '').replace(/\*\*/g, '').trim()).filter(Boolean);
  const comps = new Map();
  const flows = []; // { label, chain: [names] }
  let title = null;
  let summary = null;
  const assumptions = [];
  for (const line of lines) {
    let m;
    if ((m = line.match(/^Title\s*:\s*(.+)$/i))) { title = m[1].trim().slice(0, 80); continue; }
    if ((m = line.match(/^Summary\s*:\s*(.+)$/i))) { summary = m[1].trim(); continue; }
    if ((m = line.match(/^Assumptions?\s*:\s*(.+)$/i))) {
      for (const a of m[1].split(/,|;/)) if (a.trim() && !/^none$/i.test(a.trim())) assumptions.push(a.trim());
      continue;
    }
    if ((m = line.match(/^Components?\s*:\s*(.+)$/i))) {
      for (const part of m[1].split(/,|;/)) {
        const name = part.replace(/\([^)]*\)/g, '').replace(/\$/g, '').trim().replace(/\.+$/, '');
        if (name && name.split(/\s+/).length <= 4) comps.set(slug(name), name);
      }
      continue;
    }
    if (/^Flow/i.test(line)) {
      const labelMatch = line.match(/^Flow\s*\d*\s*\(([^)]*)\)/i);
      const body = line.replace(/^Flow\s*\d*\s*[^:]*:\s*/i, '');
      for (const seg of body.split(/,(?![^()]*\))/)) {
        if (!ARROW.test(seg)) continue;
        const chain = seg.split(ARROW).map(s => s.replace(/^[^:]*:\s*/, '').replace(/\([^)]*\)/g, '').replace(/\$/g, '').replace(/\.+$/, '').trim()).filter(Boolean);
        if (chain.length < 2) continue;
        if (chain.some(p => p.split(/\s+/).length > 4)) continue;
        for (const p of chain) if (!comps.has(slug(p))) comps.set(slug(p), p);
        flows.push({ label: (labelMatch ? labelMatch[1] : '').trim() || 'flow', chain });
      }
    }
  }
  return { comps, flows, title, summary, assumptions };
}

function compileArchitecture(parsed) {
  if (parsed.comps.size === 0) return null;
  const dirs = ['R', 'L', 'T', 'B'];
  const out = ['architecture-beta', '    group app(cloud)[Application]'];
  let i = 0;
  for (const [s, d] of parsed.comps) out.push('    service ' + s + '(' + iconType(d) + ')[' + d.slice(0, 24) + '] in app');
  const seen = new Set();
  for (const f of parsed.flows) {
    for (let k = 0; k < f.chain.length - 1; k++) {
      const a = slug(f.chain[k]);
      const b = slug(f.chain[k + 1]);
      const key = a + '|' + b;
      if (seen.has(key) || a === b) continue;
      seen.add(key);
      out.push('    ' + a + ':' + dirs[i % 4] + ' -- ' + dirs[(i + 1) % 4] + ':' + b);
      i++;
    }
  }
  return out.join('\n');
}

function compileFlowchart(parsed) {
  if (parsed.flows.length === 0) return null;
  const names = new Map();
  for (const f of parsed.flows) for (const p of f.chain) names.set(slug(p), p);
  const out = ['flowchart TD'];
  for (const [s, d] of names) out.push('    ' + s.replace(/-/g, '_') + '[' + d.slice(0, 28) + ']');
  const seen = new Set();
  for (const f of parsed.flows) {
    for (let k = 0; k < f.chain.length - 1; k++) {
      const a = slug(f.chain[k]).replace(/-/g, '_');
      const b = slug(f.chain[k + 1]).replace(/-/g, '_');
      const key = a + '|' + b + '|' + f.label;
      if (seen.has(key) || a === b) continue;
      seen.add(key);
      out.push('    ' + a + ' -->|' + f.label.slice(0, 20) + '| ' + b);
    }
  }
  return out.join('\n');
}

function compileSequence(parsed) {
  if (parsed.flows.length === 0) return null;
  const order = [];
  for (const f of parsed.flows) for (const p of f.chain) {
    const s = slug(p);
    if (!order.includes(s)) order.push(s);
  }
  const out = ['sequenceDiagram', '    autonumber'];
  for (const s of order) {
    const d = parsed.comps.get(s) || s;
    out.push('    participant ' + s.replace(/-/g, '_') + ' as ' + d.slice(0, 28));
  }
  for (const f of parsed.flows) {
    for (let k = 0; k < f.chain.length - 1; k++) {
      const a = slug(f.chain[k]).replace(/-/g, '_');
      const b = slug(f.chain[k + 1]).replace(/-/g, '_');
      if (a === b) continue;
      out.push('    ' + a + '->>' + b + ': ' + f.label.slice(0, 30));
    }
  }
  return out.join('\n');
}

/**
 * @param {string} analysisText raw model output
 * @param {{mode: 'architecture'|'flowchart'|'sequence', model: string}} opts
 * @returns {{ok: true, result: object} | {ok: false, error: {code: string, message: string}}}
 */
function compileAnalysis(analysisText, opts) {
  const mode = opts.mode || 'architecture';
  const norm = analysisText.replace(/\\rightarrow/g, '→');
  const parsed = parseAnalysis(norm);
  if (parsed.comps.size === 0) {
    return { ok: false, error: { code: 'analysis_unusable', message: 'reply missing Components/Flows structure' } };
  }
  const mermaid =
    mode === 'flowchart' ? compileFlowchart(parsed) :
    mode === 'sequence' ? compileSequence(parsed) :
    compileArchitecture(parsed);
  if (!mermaid) {
    return { ok: false, error: { code: 'analysis_unusable', message: 'reply missing Flows structure for ' + mode } };
  }
  return {
    normalized: norm,
    ok: true,
    normalized: norm,
    result: {
      title: (parsed.title || 'Architecture').slice(0, 120),
      mermaid,
      explanation: parsed.summary || 'Diagram compiled from the model analysis of the selected passage.',
      assumptions: parsed.assumptions,
      model: opts.model,
      promptVersion: (mode + '-v2-compiled'),
      componentCount: parsed.comps.size,
    },
  };
}

// n8n Validate node body — compileAnalysis() is inlined at provision time.
const resp = $json;
const prep = $('Prepare').first().json;
const jobId = prep.jobId;
let text = '';
try { text = (resp.candidates[0].content.parts || []).map(p => p.text || '').join(''); } catch (e) {}
const out = compileAnalysis(text, { mode: prep.mode, model: $env.GEMMA_MODEL });
const result = out.ok ? out.result : null;
const error = out.ok ? null : out.error;
return [{ json: { jobId, ok: !!result, result, error, rawText: out.normalized || '' } }];

